import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Login em dois fatores","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/two-factor.md","filePath":"pt-BR/guide/two-factor.md"}'),r={name:"pt-BR/guide/two-factor.md"};function t(n,o,d,g,l,u){return a(),i("div",null,[...o[0]||(o[0]=[s('<h1 id="login-em-dois-fatores" tabindex="-1">Login em dois fatores <a class="header-anchor" href="#login-em-dois-fatores" aria-label="Permalink to &quot;Login em dois fatores&quot;">​</a></h1><p>Com o login em dois fatores, entrar no Orbit pede a sua senha e um código de 6 dígitos de um app autenticador no celular, então uma senha roubada não basta sozinha. Os <a href="./api-tokens">tokens de API</a> não são afetados.</p><h2 id="turning-on" tabindex="-1">Ligando <a class="header-anchor" href="#turning-on" aria-label="Permalink to &quot;Ligando {#turning-on}&quot;">​</a></h2><ol><li>Em <strong>Configurações → Login em dois fatores</strong>, selecione <strong>Ligar</strong>.</li><li>Escaneie o QR code com um app autenticador (1Password, Google Authenticator, Authy, Bitwarden ou qualquer outro app TOTP), ou digite a chave que aparece embaixo.</li><li>Digite o código de 6 dígitos que ele mostra. O Orbit então mostra 10 <strong>códigos de recuperação</strong>, só desta vez. Copie ou baixe e guarde num lugar seguro, como um gerenciador de senhas.</li></ol><p>A partir daí, o login pede um código depois da senha.</p><h2 id="signing-in" tabindex="-1">Entrando <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Entrando {#signing-in}&quot;">​</a></h2><ul><li><strong>Digite o código atual</strong>, ou um dos seus códigos de recuperação quando estiver sem o celular. Cada código de recuperação funciona uma vez; as Configurações mostram quantos restam, e <strong>Novos códigos de recuperação</strong> troca todos.</li><li><strong>Um código funciona uma vez,</strong> então um código que alguém viu não pode ser usado de novo. O Orbit também aceita o código logo antes e logo depois do atual, caso o relógio do celular esteja um pouco fora.</li><li><strong>Códigos errados contam</strong> para o limite de login: depois de cinco falhas, aquele endereço espera um minuto.</li></ul><h2 id="turning-off" tabindex="-1">Desligando <a class="header-anchor" href="#turning-off" aria-label="Permalink to &quot;Desligando {#turning-off}&quot;">​</a></h2><p><strong>Desligar</strong> pede um código atual ou um código de recuperação. Não é possível enquanto o administrador exige o login em dois fatores.</p><h2 id="requiring" tabindex="-1">Exigindo de todos <a class="header-anchor" href="#requiring" aria-label="Permalink to &quot;Exigindo de todos {#requiring}&quot;">​</a></h2><p>O administrador do Orbit pode exigir em <strong>Configurações → Login em dois fatores</strong>, depois de ligar o dele. As Configurações mostram quantas pessoas ainda não têm, e <strong>Configurações → Membros</strong> marca quem tem.</p><ul><li><strong>Quem não tem</strong> só consegue configurar, ou sair, até configurar: o console leva à página de configuração, e a API responde <code>403 secondFactorSetupRequired</code> a todo o resto.</li><li><strong>Quem já está logado</strong> é cobrado na próxima requisição, não só no próximo login.</li><li><strong>Os tokens de API</strong> continuam funcionando.</li></ul><h2 id="lost" tabindex="-1">Celular e códigos de recuperação perdidos <a class="header-anchor" href="#lost" aria-label="Permalink to &quot;Celular e códigos de recuperação perdidos {#lost}&quot;">​</a></h2><ul><li><p><strong>O administrador do Orbit</strong> seleciona <strong>Resetar 2FA</strong> ao lado da pessoa em <strong>Configurações → Membros</strong>. Ela entra com a senha e, se for obrigatório, configura de novo.</p></li><li><p><strong>Para o próprio administrador,</strong> ou sem o console, no servidor principal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset-second-factor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ada@example.com</span></span></code></pre></div></li></ul><h2 id="storage" tabindex="-1">Como fica guardado <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Como fica guardado {#storage}&quot;">​</a></h2><p>O segredo é selado com a chave do Orbit, como os outros segredos, e vai junto no <code>orbit backup</code>. Os códigos de recuperação ficam guardados só como hashes. Códigos e segredos nunca vão para os logs.</p>',16)])])}const m=e(r,[["render",t]]);export{p as __pageData,m as default};
